/**
 * Ten digits written by real people with a stylus, kept as they were written.
 *
 * They come from the writer-independent test file of the UCI "Pen-Based Recognition of
 * Handwritten Digits" data set (E. Alpaydin and F. Alimoglu, 1998), which is distributed
 * under CC BY 4.0: https://archive.ics.uci.edu/dataset/81. Each is scaled so that its
 * longer side is 80 px, and is otherwise untouched.
 *
 * Every one of them is misread by the main model when it works alone, in the way
 * `aloneReads` records, and read correctly once the digit helpers vote. They are here so
 * that this stays true.
 */

export interface RealDigit {
  /** What the writer was asked to write. */
  digit: string;
  /** What the main model reads without the helpers. */
  aloneReads: string;
  /** Position in `pendigits-orig.tes`, counting samples from zero. */
  index: number;
  /** One flat `x, y, x, y, …` list per pen-down, in writing order. */
  strokes: number[][];
}

